-- Descrição dos tamanhos de acordo com a montagem real (árvore sanfona com mastro).
UPDATE "Product" SET "description" = 'Árvore de Natal verde tradicional que vem achatada na caixa, já decorada e com pisca-pisca instalado. Encaixe o mastro, puxe para cima e ligue na tomada. Bivolt, com enfeites inclusos (a partir de 50, conforme o tamanho).'
WHERE "type" = 'MAIN' AND "description" = 'Árvore de Natal verde tradicional que já vem montada e com pisca-pisca instalado, bivolt, com enfeites inclusos (a partir de 50, conforme o tamanho). Tira da caixa, abre os galhos e liga na tomada.';
